.tag{font-size:.68rem;font-weight:700;letter-spacing:.02em;color:#6f675c;margin:0 0 1rem;text-transform:uppercase;}
.related-item{background:#faf8f4;border:1px solid var(--line-on-grey);border-radius:10px;padding:1.1rem 1.3rem;margin-bottom:1rem;}
.related-item .ri-head{display:flex;align-items:center;gap:.6rem;flex-wrap:wrap;margin-bottom:.5rem;}
.related-item h4{font-family:var(--font-display);font-size:.92rem;font-weight:600;margin:0;color:var(--ink);}
.badge{font-size:.6rem;font-weight:700;padding:.15rem .5rem;border-radius:999px;color:#fff;text-transform:uppercase;letter-spacing:.02em;}
.badge.guclu{background:var(--green);}
.badge.olası{background:var(--amber);}
.related-item p{font-family:var(--font-serif);font-size:.9rem;color:#4a453d;line-height:1.65;margin:.4rem 0;}
.related-item details{margin-top:.5rem;}
.related-item summary{cursor:pointer;font-size:.78rem;color:var(--brass-deep);font-weight:600;}
.related-item .maker-tag{font-size:.75rem;color:var(--brass-deep);}
.related-item .maker-tag a{color:var(--brass-deep);text-decoration:none;border-bottom:1px solid var(--brass);font-weight:600;}
.related-item .src{font-size:.65rem;color:#9c9284;}
footer{color:#e8e1d7;background:#181613;display:grid;grid-template-columns:2fr 1fr;gap:2.5rem;padding:4rem 5vw 2rem;border-radius:36px 36px 0 0;margin-top:3rem;}
@media (max-width:700px){footer{grid-template-columns:1fr 1fr;padding:3rem 1.3rem 2rem;}}
.footer-brand .brand-mark{width:28px;height:28px;border:1px solid #e8e1d7;border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:var(--font-display);color:#e8e1d7;}
.footer-brand h2{font-family:var(--font-display),Georgia,serif;font-weight:500;margin:1rem 0 .2rem;font-size:2.1rem;color:#e8e1d7;}
footer p,footer a{color:#a9a197;font-size:.72rem;line-height:1.8;}
footer h3{text-transform:uppercase;letter-spacing:.15em;margin-bottom:1.2rem;font-size:.65rem;color:#a9a197;}
.footer-icon-link{align-items:center;gap:.65rem;display:inline-flex;color:#a9a197;text-decoration:none;}
.copyright{border-top:1px solid #ffffff1f;grid-column:1/-1;margin:2.5rem 0 0;padding-top:1.5rem;}
.copyright p{color:#9c9284;margin:0;}
[data-theme=dark]{--ink:#ece4d3;--paper:#100e0c;--paper-light:#17140f;--line:#ece4d324;--brass:#b8874a;--card-bg:#17140f;--muted-text:#a89e8e;}
[data-theme=dark] footer{background:#000;}
[data-theme=dark] .related-item{background:#1c1912;}
.menu-button{display:none;}
.site-header{position:relative;}
@media (max-width:820px){.nav{position:absolute;top:100%;left:0;right:0;background:var(--paper);flex-direction:column;gap:1rem;padding:1.2rem 5vw;border-bottom:1px solid var(--line);display:none;z-index:10;} .nav.is-open{display:flex;} .menu-button{display:inline-flex!important;flex-direction:column;justify-content:center;gap:5px;width:34px;height:34px;border:none;background:transparent;cursor:pointer;} .menu-button span{display:block;width:22px;height:2px;background:var(--ink);} .media-col{position:static;}}

